function toast(msg){const o=document.getElementById('overlay');o.innerHTML=`<div class="toast">${msg}</div>`;setTimeout(()=>{if(o.querySelector('.toast'))o.innerHTML=''},3000)}
function nav(page){currentPage=page;window.scrollTo({top:0,left:0,behavior:'auto'});document.getElementById('topTitle').textContent=page;window.downloadTextFile=function(name,text){const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
window.downloadPromptBook=function(){downloadTextFile('Sami_Bank_Prompt_Book.txt',`SAMI BANK — AI-ASSISTED WEB APPLICATION PROJECT\nPrompt Book (edit to reflect the prompts you actually used)\n\nPROMPT 1 — PLANNING\nAct as a UI/UX designer. Plan a responsive fictional Indian digital banking dashboard named Sami Bank with a navy, gold and white theme. Define target users, problem, objectives, pages, components and safety limitations. Do not imply real bank integration.\n\nPROMPT 2 — PROTOTYPE\nCreate a responsive banking demo using HTML, CSS and vanilla JavaScript. Include dashboard, sample accounts, transactions, simulated transfers, review/confirmation, search, filters, calculators and a fictional-bank disclaimer. Never collect real PINs, OTPs, CVVs or credentials.\n\nPROMPT 3 — TESTING\nReview navigation, invalid input, insufficient demo balance, transaction consistency, PDF/CSV exports, mobile layout and success/error messages. Report confirmed defects and distinguish tested features from simulated or untested features.\n\nPROMPT 4 — REPORT\nPrepare an academic report with problem statement, objectives, users, requirements, tools, prompt book, implementation, test cases, limitations, future scope and conclusion. Describe only features that exist.\n\nImportant: Replace or supplement these suggested prompts with your actual prompt history and actual observed outputs.`);toast('Prompt book downloaded.')};
window.downloadProjectNotes=function(){downloadTextFile('Sami_Bank_Project_Notes.txt',`SAMI BANK — BANKING BEYOND BOUNDARIES.\nAI-Assisted Web Application Project — ESE Task\n\nProblem: Banking information and workflows can be distributed across different screens. This prototype demonstrates a unified responsive dashboard.\nObjectives: Build a responsive UI, show sample account summaries, simulate transfers, provide calculators, support statement export and explain digital safety.\nUsers: Students and general users exploring an educational demo.\nTechnologies: HTML5, CSS3, vanilla JavaScript, browser localStorage for non-sensitive sample data.\nLimitations: Fictional project; no real authentication, backend, bank integration, live rates, payment processing, card issuance or loan approval.\nTesting: Use the in-app checklist and download a test log after personally verifying each item.\nFuture scope: Accessibility review, more automated tests, improved validation and optional sandbox backend.\n`);toast('Project notes downloaded.')};
window.saveTestChecks=function(){const a=[...document.querySelectorAll('[data-test]')].map(x=>x.checked);try{localStorage.setItem('samiTestChecks',JSON.stringify(a))}catch(e){}};
window.clearTestChecks=function(){document.querySelectorAll('[data-test]').forEach(x=>x.checked=false);try{localStorage.removeItem('samiTestChecks')}catch(e){}toast('Checklist cleared.')};
window.downloadTestReport=function(){const items=[...document.querySelectorAll('[data-test]')];const lines=items.map(x=>`${x.checked?'[CHECKED]':'[NOT VERIFIED]'} ${x.parentElement.innerText.trim()}`);downloadTextFile('Sami_Bank_Test_Log.txt','SAMI BANK — TEST LOG\nDate: '+new Date().toLocaleString()+'\n\n'+lines.join('\n')+'\n\nNote: Checked items represent user-marked checks, not independently verified test results.');toast('Test log downloaded.')};

document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('sidebar').classList.remove('open');render()}
function go(page){nav(page)}
function card(title,body,extra=''){return `<section class="card ${extra}"><div class="section-head"><h3>${title}</h3></div>${body}</section>`}
function txRows(items=tx){return items.map(t=>`<tr><td><div class="merchant"><span class="merchant-icon">${t.icon||'↔'}</span><div><b>${esc(t.name)}</b><div class="subtle">${esc(t.type)}</div></div></div></td><td>${esc(t.date)}</td><td class="${t.amount<0?'negative':'positive'}">${t.amount<0?'−':'+'}${money(Math.abs(t.amount))}</td><td><span class="status">${esc(t.status)}</span></td><td><button class="btn btn-light" onclick="receipt('${t.id}')">Receipt</button></td></tr>`).join('')}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function table(items=tx){return `<div class="table-wrap"><table class="transactions"><thead><tr><th>TRANSACTION</th><th>DATE</th><th>AMOUNT</th><th>STATUS</th><th></th></tr></thead><tbody>${txRows(items)}</tbody></table></div>`}
function stat(label,value,icon,foot){return `<div class="card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function quick(icon,label,page){return `<button class="quick" onclick="go('${page}')"><span class="qicon">${icon}</span>${label}</button>`}
function service(icon,title,desc,page){return `<div class="card service-card" onclick="go('${page}')"><div class="service-icon">${icon}</div><h3>${title}</h3><p>${desc}</p><span class="link">Explore service →</span></div>`}
