function depositCompound(principal,rate,years,type){const n=type==='monthly'?12:type==='quarterly'?4:type==='yearly'?1:0;const r=rate/100;if(type==='simple')return principal*(1+r*years);return principal*Math.pow(1+r/n,n*years)}
function refreshDepositEstimate(){const p=Number(document.getElementById('depositPrincipal')?.value),rate=Number(document.getElementById('depositRate')?.value),years=Number(document.getElementById('depositYears')?.value),type=document.getElementById('depositCalcType')?.value;if(!(p>0)||rate<0||!(years>0))return;const maturity=depositCompound(p,rate,years,type),interest=maturity-p;const fmt=n=>money(n);document.getElementById('depositInvestment').textContent=fmt(p);document.getElementById('depositInterest').textContent=fmt(interest);document.getElementById('depositMaturity').textContent=fmt(maturity)}
