window.updateInvestAllocation=function(){const profile=document.getElementById('investRiskProfile')?.value||'moderate';const configs={conservative:{equity:25,debt:55,cash:20,note:'A conservative illustration prioritises stability and liquidity, while still including some exposure to growth assets. It is not a recommendation.'},moderate:{equity:55,debt:30,cash:15,note:'This is an illustrative example for educational purposes only. Actual allocation depends on your goals, risk profile, time horizon and market conditions.'},growth:{equity:75,debt:15,cash:10,note:'A growth-oriented illustration has a larger equity allocation and may experience greater volatility and losses. It is not a recommendation.'}};const c=configs[profile];const donut=document.getElementById('investDonut');if(donut)donut.style.background=`conic-gradient(#2168d7 0 ${c.equity}%,#f0b323 ${c.equity}% ${c.equity+c.debt}%,#68a9f7 ${c.equity+c.debt}% 100%)`;const legend=document.getElementById('investLegend');if(legend)legend.innerHTML=`<div class="invest-legend-row"><span class="invest-legend-dot" style="background:#2168d7"></span><div><b>Equity (fictional)</b><small>For long-term growth</small></div><strong>${c.equity}%</strong></div><div class="invest-legend-row"><span class="invest-legend-dot" style="background:#f0b323"></span><div><b>Debt (fictional)</b><small>For stability and regular income</small></div><strong>${c.debt}%</strong></div><div class="invest-legend-row"><span class="invest-legend-dot" style="background:#68a9f7"></span><div><b>Cash (fictional)</b><small>For liquidity and short-term needs</small></div><strong>${c.cash}%</strong></div>`;const note=document.getElementById('investAllocationNote');if(note)note.textContent=c.note;};
window.investPortfolioInfo=function(){openInvestTool('allocation')};
window.openInvestTool=function(kind){const details={risk:['Understanding your risk profile','Your comfort with changes in value, time horizon, goals and ability to absorb losses all matter. Diversification can spread exposure but cannot eliminate investment risk.'],life:['Life & term insurance','Life insurance can provide financial support to chosen beneficiaries if the insured person dies during the policy term. Compare cover, exclusions, premium terms and claim conditions before choosing a real policy.'],health:['Health insurance basics','Review sum insured, room limits, co-payments, waiting periods, exclusions, network hospitals and renewal terms. This educational prototype does not compare or sell real policies.'],tax:['Tax-saving concepts','ELSS, PPF and NPS have different lock-in periods, risks, tax treatment and eligibility rules. Tax rules change; check current official guidance or consult a qualified tax professional.'],allocation:['About sample allocations','These percentages are fictional examples used to explain asset allocation. They are not a personal recommendation, investment offer or prediction of returns.'],retirement:['Retirement planning','A retirement estimate depends on your target age, monthly contribution, assumed returns, inflation and current savings. The calculator below is illustrative and returns are not guaranteed.']};if(kind==='sip'||kind==='retirement'){const isRet=kind==='retirement';document.getElementById('overlay').innerHTML=`<div class="modal-backdrop invest-modal" onclick="if(event.target===this)this.remove()"><div class="modal"><h3>${isRet?'Retirement savings planner':'SIP calculator'}</h3><p>Enter sample values to estimate a hypothetical future value. Assumed returns are not guaranteed and this is not financial advice.</p><form id="investCalcForm"><div class="invest-modal-form"><div class="field"><label for="investMonthly">Monthly contribution (₹)</label><input id="investMonthly" type="number" min="100" step="100" value="5000" required></div><div class="field"><label for="investReturn">Assumed annual return (%)</label><input id="investReturn" type="number" min="0" max="40" step="0.5" value="12" required></div><div class="field"><label for="investYears">Investment period (years)</label><input id="investYears" type="number" min="1" max="50" value="10" required></div></div><div id="investCalcResult" class="invest-modal-result" aria-live="polite"><span>Estimated future value</span><strong>₹11,61,695</strong><p>Illustrative calculation based on monthly contributions.</p></div><div class="modal-actions"><button class="btn btn-light" type="button" onclick="document.getElementById('overlay').innerHTML=''">Close</button><button class="btn btn-primary" type="submit">Calculate estimate</button></div></form></div></div>`;const form=document.getElementById('investCalcForm');form.onsubmit=e=>{e.preventDefault();const m=Number(document.getElementById('investMonthly').value),r=Number(document.getElementById('investReturn').value)/1200,n=Number(document.getElementById('investYears').value)*12;if(!(m>0)||r<0||!(n>0)){toast('Enter valid sample values.');return}const fv=r===0?m*n:m*((Math.pow(1+r,n)-1)/r)*(1+r),invested=m*n,fmt=money(fv),el=document.getElementById('investCalcResult');el.innerHTML=`<span>Estimated future value</span><strong>${fmt}</strong><p>Total contributions: ${money(invested)} · Illustrative growth: ${money(fv-invested)}</p>`};return}const d=details[kind]||details.allocation;document.getElementById('overlay').innerHTML=`<div class="modal-backdrop invest-modal" onclick="if(event.target===this)this.remove()"><div class="modal"><h3>${esc(d[0])}</h3><p>${esc(d[1])}</p><div class="notice" style="margin:14px 0 0">Illustrative educational content only. This is not financial, tax or insurance advice and no product is being offered.</div><div class="modal-actions"><button class="btn btn-primary" type="button" onclick="document.getElementById('overlay').innerHTML=''">Got it</button></div></div></div>`};

