window.chooseLoan=function(name,rate,tenure){const principal=document.getElementById('principal'),rateInput=document.getElementById('rate'),years=document.getElementById('years');if(principal&&rateInput&&years){rateInput.value=rate;years.value=String(tenure);document.getElementById('calcType').value='monthly';principal.scrollIntoView({behavior:'smooth',block:'center'});const e=new Event('input',{bubbles:true});principal.dispatchEvent(e);rateInput.dispatchEvent(e);years.dispatchEvent(e);toast(name+' selected. Illustrative rate applied; no application is submitted.')}else toast(name+' is an illustrative loan product.')};
