function business(){
const kpi=(label,value,icon,foot,tone='',bars='')=>`<div class="business-kpi ${tone}"><div class="business-kpi-top"><span>${label}</span><span class="business-kpi-icon">${icon}</span></div><div class="business-kpi-value">${value}</div><div class="business-kpi-foot">${foot}</div>${bars?`<div class="business-spark" aria-hidden="true">${bars.split(',').map(h=>`<i style="height:${h}px"></i>`).join('')}</div>`:''}</div>`;
const svc=(tone,icon,title,desc,bullets,art,page)=>`<article class="business-service ${tone}" role="button" tabindex="0" onclick="go('${page}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();go('${page}')}" aria-label="Explore ${title}"><div class="business-service-main"><div class="business-service-icon">${icon}</div><h3>${title}</h3><p>${desc}</p><ul class="business-bullets">${bullets.map(x=>`<li>${x}</li>`).join('')}</ul><button class="btn btn-outline" onclick="event.stopPropagation();go('${page}')">Explore service <span aria-hidden="true">→</span></button></div><div class="business-service-art" aria-hidden="true"><span class="art-halo"></span>${art}</div></article>`;
return `<div class="business-page"><div class="business-heading"><div><h1 class="page-title">Business Banking</h1><p class="page-desc">Banking tools to help your business manage payments, invoices and cash flow.</p></div><button class="btn btn-outline business-apply" onclick="window.showBusinessAccountInfo()">Apply for business account <span aria-hidden="true">→</span></button></div>
<div class="business-kpis">${kpi('Business demo balance',money(248500),'▦','<span class="gain">↑ 12.4%</span> <span>from last month</span>','', '18,28,35,46')}${kpi('Incoming invoices',money(78500),'▤','3 pending sample invoices','green','17,25,34,45')}${kpi('Outgoing payments',money(42600),'↘','This month · sample data','rose','18,27,36,45')}${kpi('Cash flow',money(35900),'◔','Net inflow · illustrative','amber','15,24,18,32')}</div>
<div class="business-service-grid">${svc('','▥','Business current account','Manage day-to-day business transactions with flexible account tools.',['Account overview and balances','Transaction activity','Account management','<span>Illustrative account only</span>'],'<div class="business-art-card">Sami Bank<small>BUSINESS ACCOUNT</small></div>','Accounts')}${svc('violet','⇄','Bulk payment workflow','Review a sample workflow for paying vendors, employees or partners.',['Manual beneficiary entry','Review payment details','Sample payment status'],'<div class="business-art-doc"></div><div style="position:absolute;right:4px;bottom:4px;z-index:2;border-radius:50%;background:#7849ee;color:#fff;width:35px;height:35px;display:grid;place-items:center;font-weight:800;box-shadow:0 5px 12px #7849ee44">₹</div>','Payments')}${svc('green','▤','Invoice tracking','Create and review fictional business invoice statuses.',['View invoice status','Payment reminders','Download sample reports'],'<div class="business-art-doc"></div><div style="position:absolute;right:1px;bottom:2px;z-index:2;border-radius:50%;background:#13b77a;color:#fff;width:34px;height:34px;display:grid;place-items:center;font-weight:900;box-shadow:0 5px 12px #13b77a44">✓</div>','Business Banking')}${svc('amber','▥','Working capital','Estimate business finance repayments with an illustrative calculator.',['Business loan EMI calculator','Flexible tenure examples','Illustrative interest rates'],'<div class="business-art-coin">▤</div>','Loans')}${svc('rose','▰','Corporate cards','Explore sample company card controls and spending guidance.',['Spending limit concepts','Card control overview','Sample activity and statements'],'<div class="business-art-card">Sami Bank<small>BUSINESS CARD　 ▰</small></div>','Cards')}${svc('','◔','Cash flow planning','Understand cash movement with simple sample planning tools.',['Cash flow summary','Income vs. expense trends','Sample report overview'],'<div class="business-art-chart"><i></i><i></i><i></i><i></i></div>','Business Banking')}</div>
<div class="business-info"><div class="business-info-icon">♧</div><div class="business-info-copy"><h3>Important information</h3><p>All balances, invoices, payment statuses, and business services shown here are fictional examples for educational use. Sami Bank is not a licensed financial institution and does not process real accounts, applications or transactions.</p></div><button class="btn btn-outline" onclick="window.showBusinessAccountInfo()">Learn more →</button></div></div>`}
window.showBusinessAccountInfo=function(){document.getElementById('overlay').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal"><h3>Business Banking — demo information</h3><p>This page demonstrates common business-banking concepts, including current accounts, bulk payments, invoices, corporate cards and cash-flow planning.</p><p><b>Important:</b> Sami Bank is a fictional educational prototype. No business account application is submitted, and no real payments, accounts or financial services are connected.</p><div class="modal-actions"><button class="btn btn-primary" onclick="document.getElementById('overlay').innerHTML=''">Close</button></div></div></div>`};
function projectDocs(){return `<h1 class="page-title">Project Documentation</h1>
<p class="page-desc">ESE Task · AI-Assisted Web Application Project. This section records the project plan, prompt book, testing checklist and limitations.</p>
<div class="notice"><b>Academic prototype notice:</b> Sami Bank is fictional. It is not affiliated with HDFC Bank or any financial institution and is not connected to real banking systems.</div>
<div class="grid two-col">
 ${card('1. Problem statement',`<p style="font-size:12px;line-height:1.8">Banking services can be spread across multiple screens and workflows. This project demonstrates how a simple, organised digital banking dashboard can present common banking information and educational tools in one responsive interface.</p>`)}
 ${card('2. Project objectives',`<ul style="font-size:12px;line-height:1.9;padding-left:18px"><li>Create a clear dashboard and responsive navigation.</li><li>Demonstrate account summaries and transaction history.</li><li>Build simulated payment and bill workflows.</li><li>Provide educational deposit and loan calculators.</li><li>Use AI prompts to plan, generate, test and improve the prototype.</li></ul>`)}
 ${card('3. Target users',`<p style="font-size:12px;line-height:1.8">Students and general users who want to explore a sample banking dashboard for learning and demonstration. It is not intended for real customers or actual banking transactions.</p>`)}
 ${card('4. Basic requirements',`<ul style="font-size:12px;line-height:1.9;padding-left:18px"><li>Responsive dashboard and service navigation.</li><li>Sample account balance and transaction records.</li><li>Payment review and simulated confirmation.</li><li>Search, filters, receipt and statement export.</li><li>Calculators, support demo and safety guidance.</li><li>Clearly visible educational disclaimer.</li></ul>`)}
</div>
<div style="height:18px"></div>
${card('5. Prompt book — prompts used / improved',`<p class="subtle" style="line-height:1.7">Keep this record with your project report. These are suggested project prompts based on the implemented prototype; edit them to match the exact prompts you personally used and the outputs you observed.</p>
<div class="field" style="margin:14px 0"><label>Prompt 1 — Planning the application</label><textarea rows="3" readonly>Act as a UI/UX designer. Plan a responsive fictional Indian digital banking dashboard named Sami Bank with a navy, gold and white theme. Define the target users, problem statement, objectives, pages, reusable components and safety limitations. Do not imply real bank integration.</textarea></div>
<div class="field" style="margin:14px 0"><label>Prompt 2 — Building the prototype</label><textarea rows="3" readonly>Create a responsive banking demo using HTML, CSS and vanilla JavaScript. Include dashboard cards, sample accounts, transaction history, simulated UPI/bill payments, review and confirmation, search, filters, calculators, and a prominent fictional-bank disclaimer. Never collect real PINs, OTPs, CVVs or credentials.</textarea></div>
<div class="field" style="margin:14px 0"><label>Prompt 3 — Testing and improvement</label><textarea rows="3" readonly>Review the prototype for broken navigation, invalid form input, insufficient demo balance, transaction consistency, PDF/CSV export, mobile responsiveness and clear success/error messages. List confirmed defects, fix them, and distinguish tested features from untested or simulated features.</textarea></div>
<div class="field" style="margin:14px 0"><label>Prompt 4 — Documentation</label><textarea rows="3" readonly>Prepare academic project documentation for Sami Bank with problem statement, objectives, target users, requirements, tools and technologies, AI prompt book, implementation summary, test cases, limitations, future scope and conclusion. Describe only features that actually exist in the prototype.</textarea></div>
<button class="btn btn-outline" onclick="downloadPromptBook()">⇩ Download prompt book (.txt)</button>`)}
<div style="height:18px"></div>
${card('6. Testing checklist',`<p class="subtle">Tick each item only after you personally verify it in your browser. These checkboxes are a working checklist, not proof that a test has passed.</p>
<div id="testChecklist" style="display:grid;gap:13px;margin-top:14px">${[
'Dashboard loads and navigation opens the correct pages',
'Mobile layout works at a narrow viewport',
'Transfer form rejects empty or invalid amounts',
'Transfer is blocked when the demo balance is insufficient',
'Successful demo transfer updates balance and transaction history',
'Transaction search and type filters work',
'PDF statement downloads and opens correctly',
'CSV statement downloads and opens correctly',
'Loan / deposit calculator produces a result',
'Reset account data restores the initial sample data',
'No real banking credentials are requested or stored'
].map((s,i)=>`<label style="display:flex;gap:10px;align-items:flex-start;font-size:12px"><input type="checkbox" data-test="${i}" onchange="saveTestChecks()"> <span>${s}</span></label>`).join('')}</div>
<div class="form-actions"><button class="btn btn-light" onclick="clearTestChecks()">Clear checklist</button><button class="btn btn-primary" onclick="downloadTestReport()">Download test log</button></div>`)}
<div style="height:18px"></div>
${card('7. Implementation status & limitations',`<div class="table-wrap"><table class="transactions"><thead><tr><th>FEATURE</th><th>STATUS</th><th>NOTES</th></tr></thead><tbody>
<tr><td>Dashboard & navigation</td><td><span class="pill">Implemented as prototype</span></td><td>Responsive frontend UI</td></tr>
<tr><td>Demo transfers & transactions</td><td><span class="pill">Simulated</span></td><td>Local browser sample data only</td></tr>
<tr><td>PDF / CSV statements</td><td><span class="pill">Needs browser verification</span></td><td>Open downloaded files and inspect output</td></tr>
<tr><td>Loan / deposit calculators</td><td><span class="pill">Educational demo</span></td><td>Illustrative rates, not offers</td></tr>
<tr><td>Authentication & backend</td><td><span class="pill">Not implemented</span></td><td>No real login or server database</td></tr>
<tr><td>Live payments / bank integration</td><td><span class="pill">Not implemented</span></td><td>No actual money movement</td></tr>
<tr><td>Live hosting link</td><td><span class="pill">Separate step required</span></td><td>Deploy before submitting a working link</td></tr>
</tbody></table></div>`)}
<div style="height:18px"></div>
${card('8. Future scope & conclusion',`<p style="font-size:12px;line-height:1.8">Future improvements may include automated accessibility testing, more robust form validation, a backend with secure authentication for a non-financial sandbox, automated unit tests, improved transaction filtering and a formal project report. The current application demonstrates AI-assisted planning and frontend prototyping, but is not a production banking system.</p><button class="btn btn-primary" onclick="downloadProjectNotes()">Download project notes (.txt)</button>`)}
`}

