function updateLiveGreeting(){
 const now=new Date();
 const hour=Number(new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',hourCycle:'h23'}).format(now));
 const greeting=hour>=5&&hour<12?'Good morning':hour>=12&&hour<17?'Good afternoon':'Good evening';
 const greetingEl=document.getElementById('liveGreeting');
 const dateEl=document.getElementById('liveSnapshotDate');
 if(greetingEl) greetingEl.textContent=`${greeting}, Aashish 👋`;
 if(dateEl) dateEl.textContent="Here's your financial snapshot for "+new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now)+'.';
}

