window.showAccountDetails=function(i){const data=[['Savings Account','4821 6703 9475',balance],['Current Account','1092 3345 6677',32500],['Salary Account','7634 8821 4456',18250],['NRI Account','5418 9932 1100',1290000]][i];if(!data)return;document.getElementById('overlay').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal"><h3>${data[0]}</h3><p>Account overview and available services.</p><hr style="border:0;border-top:1px solid var(--line)"><p>Account holder: <b>Aashish Kumar</b></p><p>Account number: <b>•••• •••• ${data[1].slice(-4)}</b></p><p>Available balance: <b>${new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(data[2])}</b></p><p>Account status: <span class="status">Active</span></p><p class="subtle">Displayed account information is illustrative and not connected to a real bank.</p><div class="modal-actions"><button class="btn btn-light" onclick="document.getElementById('overlay').innerHTML=''">Close</button><button class="btn btn-primary" onclick="document.getElementById('overlay').innerHTML='';nav('Transactions')">View transactions</button></div></div></div>`;};
window.accountAction=function(action,i){if(action==='statement'){nav('Transactions');toast('Showing sample transaction history.');return}if(action==='transfer'){nav('Payments');toast('Use the transfer form to start a simulated transfer.');return}if(action==='more'){const names=['Savings Account','Current Account','Salary Account','NRI Account'];document.getElementById('overlay').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal"><h3>${names[i]} — More options</h3><p>Choose an account service to explore.</p><div class="form-actions"><button class="btn btn-outline" onclick="document.getElementById('overlay').innerHTML='';confirmDemo('Account statement request')">Statement request</button><button class="btn btn-outline" onclick="document.getElementById('overlay').innerHTML='';confirmDemo('Account service request')">Service request</button></div><div class="modal-actions"><button class="btn btn-light" onclick="document.getElementById('overlay').innerHTML=''">Close</button></div></div></div>`;}};
window.openAccountRequest=function(){document.getElementById('overlay').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal"><h3>Explore account options</h3><p>Select an account type to review a sample application workflow.</p><div class="form-actions" style="display:grid;grid-template-columns:1fr 1fr"><button class="btn btn-outline" onclick="document.getElementById('overlay').innerHTML='';confirmDemo('Savings account application')">Savings Account</button><button class="btn btn-outline" onclick="document.getElementById('overlay').innerHTML='';confirmDemo('Current account application')">Current Account</button><button class="btn btn-outline" onclick="document.getElementById('overlay').innerHTML='';confirmDemo('Salary account application')">Salary Account</button><button class="btn btn-outline" onclick="document.getElementById('overlay').innerHTML='';confirmDemo('NRI account application')">NRI Account</button></div><p class="subtle">This is a local prototype workflow; no bank account is opened.</p><div class="modal-actions"><button class="btn btn-light" onclick="document.getElementById('overlay').innerHTML=''">Close</button></div></div></div>`;};
window.editNominee=function(){document.getElementById('overlay').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal"><h3>Nominee Information</h3><p>Update the sample nominee details for this browser session.</p><form id="nomineeForm"><div class="field"><label>Nominee name</label><input id="nomineeNameInput" maxlength="60" value="${esc(document.getElementById('nomineeNameDisplay')?.textContent||'Demo Nominee')}" required></div><div class="field" style="margin-top:12px"><label>Relationship</label><select id="nomineeRelationInput"><option>Not Specified</option><option>Parent</option><option>Spouse</option><option>Child</option><option>Sibling</option><option>Other</option></select></div><div class="modal-actions"><button type="button" class="btn btn-light" onclick="document.getElementById('overlay').innerHTML=''">Cancel</button><button class="btn btn-primary" type="submit">Save sample details</button></div></form></div></div>`;document.getElementById('nomineeForm').onsubmit=e=>{e.preventDefault();const n=document.getElementById('nomineeNameInput').value.trim();if(n){document.getElementById('nomineeNameDisplay').textContent=n;const relation=document.getElementById('nomineeRelationInput').value;const copy=document.querySelector('.nominee-copy span');if(copy)copy.textContent='Relation: '+relation;document.getElementById('overlay').innerHTML='';toast('Sample nominee details updated locally.')}};};

window.searchHelp=function(e){if(e)e.preventDefault();const input=document.getElementById('helpSearchInput');const q=(input?.value||'').trim().toLowerCase();document.querySelectorAll('#helpFaqList .help-faq').forEach(el=>{el.hidden=!!q&&!el.dataset.search.includes(q)});const empty=document.getElementById('helpFaqEmpty');if(empty)empty.hidden=!!document.querySelector('#helpFaqList .help-faq:not([hidden])');document.querySelectorAll('.help-topic-tab').forEach(b=>b.classList.remove('active'));const panel=document.getElementById('helpFaqPanel');if(panel)panel.scrollIntoView({behavior:'smooth',block:'start'});return false};
window.filterHelpTopic=function(topic){const q=(document.getElementById('helpSearchInput')?.value||'').trim().toLowerCase();document.querySelectorAll('.help-topic-tab').forEach(b=>b.classList.toggle('active',b.dataset.topic===topic));document.querySelectorAll('#helpFaqList .help-faq').forEach(el=>{const topicMatch=topic==='All topics'||el.dataset.topic===topic;el.hidden=!(topicMatch&&(!q||el.dataset.search.includes(q)))});const empty=document.getElementById('helpFaqEmpty');if(empty)empty.hidden=!!document.querySelector('#helpFaqList .help-faq:not([hidden])')};
window.trackSupportRequest=function(){document.getElementById('overlay').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal"><h3>Track a support request</h3><p>Enter a demo ticket ID created in this page. This tracker does not connect to a real support system.</p><form id="trackDemoForm"><div class="field"><label for="trackDemoId">Request ID</label><input id="trackDemoId" placeholder="e.g. DEMO-123456" required></div><div id="trackDemoResult" style="margin-top:12px"></div><div class="modal-actions"><button type="button" class="btn btn-light" onclick="document.getElementById('overlay').innerHTML=''">Close</button><button type="submit" class="btn btn-primary">Check status</button></div></form></div></div>`;document.getElementById('trackDemoForm').onsubmit=e=>{e.preventDefault();const id=document.getElementById('trackDemoId').value.trim().toUpperCase();document.getElementById('trackDemoResult').innerHTML=/^DEMO-\d{6}$/.test(id)?`<div class="result">Request <b>${esc(id)}</b><br>Status: <span class="status">Received · local demo only</span><br><small>No real support ticket has been created or checked.</small></div>`:`<div class="result">No matching demo ID format. Enter an ID like DEMO-123456.</div>`}};
window.openHelpContact=function(kind){document.getElementById('overlay').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal"><h3>Contact Sami Bank demo support</h3><p>These contact details are illustrative and are not verified or connected to a real bank support desk.</p><div class="notice" style="margin:12px 0">Phone: 1800 202 1234<br>Email: support@samibank.com<br>Live chat: simulated in this educational prototype.</div><div class="modal-actions"><button class="btn btn-light" onclick="document.getElementById('overlay').innerHTML=''">Close</button><button class="btn btn-primary" onclick="document.getElementById('overlay').innerHTML='';toast('Demo support chat is not connected to a live agent.')">Open demo chat</button></div></div></div>`};
window.reportDemoFraud=function(){document.getElementById('overlay').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal"><h3>Report suspicious activity</h3><p>This demo cannot receive or submit a real fraud report.</p><div class="notice" style="margin:12px 0">If you suspect fraud, contact your actual bank immediately using the verified number in its official app or website. In India, cyber financial fraud can also be reported through official government channels.</div><div class="modal-actions"><button class="btn btn-primary" onclick="document.getElementById('overlay').innerHTML=''">Understood</button></div></div></div>`};
window.showSecurityInfo=function(kind){const data=kind==='phishing'?['Spot phishing','Watch for unexpected urgency, misspelled sender addresses, suspicious links and requests for passwords or OTPs. Open official websites by typing the address yourself.']:['Recognise unfamiliar login activity','This screen uses fictional examples only and cannot detect real logins or protect your account. If you suspect unauthorised access, contact your actual bank through its official app, website or phone number.'];document.getElementById('overlay').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal"><h3>${data[0]}</h3><p>${data[1]}</p><p><b>Reminder:</b> Sami Bank is an educational prototype and does not provide real security monitoring or fraud reporting.</p><div class="modal-actions"><button class="btn btn-primary" onclick="document.getElementById('overlay').innerHTML=''">Got it</button></div></div></div>`};
